import { initCurrentUser } from "../../utils/currentUser";
import { logVerbose } from "../../utils/logVerbose";
import {
  addMessageListener,
  addMessageListenerExternal,
} from "../../utils/message";
import { openInterviewAssistant } from "../../utils/popup";
import {
  captureException,
  captureMessage,
  initSentry,
} from "../../utils/sentry";
import { getUiConfigSw } from "../../utils/ui-config";
import {
  checkUrlMatches,
  reloadContentScriptUrls,
  type UrlMappings,
} from "../../utils/url";

initCurrentUser();
initSentry();

const ALLOWED_ORIGINS: UrlMappings = {
  matches: [
    "https://*.brighthire.ai",
    "https://app.ashbyhq.com",
    "https://*.greenhouse.io",
    "https://hire.lever.co",
    "https://*.smartrecruiters.com",
    "https://*.workday.com",
    "https://myworkday.com",
    "https://*.myworkday.com",
    "https://match.app.jobvite.com",
    "https://calendar.google.com",
    "https://outlook.office.com",
    "https://outlook.office365.com",
    "https://outlook.live.com",
    "https://*.icims.com",
    "https://*.tam.inforcloudsuite.com",
    "https://*.workable.com",
    "https://*.bullhornstaffing.com",
    "https://www.gem.com",
  ],
  excludes: [],
};
chrome.management.getSelf().then((info) => {
  ALLOWED_ORIGINS.matches.push(`chrome-extension://${info.id}`);
  if (
    info.hostPermissions.some((glob) => glob.includes("https://localhost:3000"))
  ) {
    ALLOWED_ORIGINS.matches.push("https://localhost:3000");
  }
});

const isAllowedOrigin = (
  sender: chrome.runtime.MessageSender | undefined,
): boolean => {
  return !!sender?.origin && checkUrlMatches(sender.origin, ALLOWED_ORIGINS);
};

/**
 * NOTE: any module-scoped variables (like `externalPorts`) will be *wiped away*
 * anytime the service worker becomes inactive. This usually happens every 30 seconds
 * without any activity.
 *
 * You should not assume that any module-scoped variables are persistent. We
 * need to account for that elsewhere, *or* use the storage API for persisting
 * JSON-serializable state
 *
 * https://developer.chrome.com/docs/extensions/develop/concepts/service-workers/lifecycle#persist-data
 */

/** Map of currently opened message ports */
const externalPorts = new Map<number, chrome.runtime.Port[]>();

const handleMessage: MessageListener = ({ message, sender }) => {
  if (!isAllowedOrigin(sender)) {
    captureMessage("Extension message from unknown origin", {
      extra: {
        origin: sender?.origin,
        url: sender?.url,
        message: message.action,
        payload: message.payload,
      },
    });
    return;
  }
  const { action, payload } = message;
  logVerbose("handleMessage", message);
  switch (action) {
    case "getVersion": {
      const manifest = chrome.runtime.getManifest();
      return { version: manifest.version };
    }
    case "getTabId": {
      if (sender.tab?.id == null) {
        captureMessage(`Missing sender tabId`, {
          extra: { message, sender },
        });
      }
      return { tabId: sender.tab?.id };
    }
    case "getUiConfig": {
      return getUiConfigSw().then((uiConfig) => {
        return { uiConfig };
      });
    }
    case "gaEvent":
    case "pullScorecard":
    case "fillScorecardV3Start":
    case "pullCandidateNotes":
    case "scorecardFilled":
    case "scorecardFeedback":
    case "customTemplateSaved":
    case "customTemplateApplied":
      externalPorts.get(sender.tab?.id as number)?.forEach((port) => {
        port.postMessage(message);
      });
      return;
    case "openUrl": {
      if (payload?.url == null) {
        captureMessage(`Missing url`, {
          extra: { message, sender },
        });
        break;
      }
      console.info(`Opening url ${payload.url}`);
      chrome.tabs.create({
        url: payload.url,
        active: true,
      });
      break;
    }
    case "openIA": {
      console.info(
        `Opening Interview assistant with url ${payload?.url ?? "undefined"}`,
      );
      openInterviewAssistant(payload?.url, payload?.windowAvailHeight);
      break;
    }
    case "toggleDrawer":
    case "getScorecardItems":
    case "openDrawer":
    case "openDrawerToast":
    case "closeDrawerToast":
    case "disableDrawerToast":
    case "enableDrawerToast":
    case "setToastText":
    case "fillScorecard":
    case "fillScorecardV3Ready":
    case "fillScorecardV3Response":
    case "fillCandidateNotes":
    case "candidateNotesStatus":
    case "setPostFillAlert":
    case "showAlert":
    case "clearAlert":
    case "showFeedback":
    case "showModal":
    case "hideModal":
    case "showCustomTemplateStudio":
    case "drawerLoading":
    case "loadingComplete": {
      if (payload?.tabId == null) {
        captureMessage(`Missing tabId`, {
          extra: { message, sender },
        });
        break;
      }
      const response = chrome.tabs.sendMessage(payload.tabId, {
        action,
        payload,
      });
      return response;
    }
    case "ghCandidateScriptVersion": {
      if (sender.tab?.id !== undefined) {
        chrome.tabs.sendMessage(sender.tab.id, message);
      }
      break;
    }
    default: {
      // support deprecated properties
      if (message.openUrl != null) {
        chrome.tabs.create({
          url: message.payload?.url,
          active: true,
        });
        return;
      }
      if (message.iaUrl != null) {
        openInterviewAssistant(message.iaUrl);
      }
    }
  }
};

addMessageListener(handleMessage);
addMessageListenerExternal(handleMessage);

chrome.runtime.onConnectExternal.addListener((port) => {
  if (!isAllowedOrigin(port.sender)) {
    captureMessage("Extension connection from unknown origin", {
      extra: {
        origin: port.sender?.origin,
        url: port.sender?.url,
        portName: port.name,
      },
    });
    return;
  }
  const tabId = port.sender?.tab?.id;
  if (tabId === undefined) return;
  if (!externalPorts.has(tabId)) {
    externalPorts.set(tabId, []);
  }
  externalPorts.get(tabId)?.push(port);
  port.onDisconnect.addListener(() => {
    const ports = externalPorts.get(tabId) ?? [];
    const index = ports.indexOf(port);
    if (index !== -1) {
      ports.splice(index, 1);
    }
    if (ports.length === 0) {
      externalPorts.delete(tabId);
    }
  });
});

chrome.action.onClicked.addListener(() => {
  try {
    openInterviewAssistant();
  } catch (err) {
    captureException(err);
    throw err;
  }
});
chrome.runtime.onInstalled.addListener((details) => {
  // reload all content script tabs on install (excludes <all_urls> pattern)
  const manifest = chrome.runtime.getManifest() as chrome.runtime.ManifestV3;
  captureMessage("User install", {
    extra: { ...details, currentVersion: manifest.version },
  });
  reloadContentScriptUrls(manifest);
});
// Force updates to be installed when available
// https://developer.chrome.com/docs/extensions/reference/runtime/#event-onUpdateAvailable
chrome.runtime.onUpdateAvailable.addListener((details) =>
  chrome.runtime.reload(),
);

chrome.tabs.onUpdated.addListener((tabId, changeInfo, tab) => {
  if (changeInfo.title) {
    chrome.tabs.sendMessage(tabId, {
      action: "tabTitleChanged",
      payload: {
        text: changeInfo.title,
      },
    });
  }

  /**
   * Rather than test a change to this handler's logic across a myriad
   * of web pages to ensure nothing breaks, opting instead for a new, greenfield
   * event here
   */
  if (changeInfo.url) {
    chrome.tabs.sendMessage(tabId, {
      action: "tabUrlChanged",
      payload: {
        url: changeInfo.url,
      },
    });
  }

  const isWorkday = changeInfo.url?.includes("workday.com/");
  const isLever = changeInfo.url?.includes("hire.lever.co/");

  // Deprecated
  if (isWorkday) {
    /**
     * Workday's tabs.onUpdated lifecycle is a bit wonky
     * When we get a changeInfo.url, the tab.status is ALWAYS still "loading"
     * So, we need to call sendMessage when it's in a loading state
     * But it must be in the "complete" state for handleTabUpdate to work properly
     */
    setTimeout(() => {
      chrome.tabs.sendMessage(tabId, {
        action: "handleTabUpdate",
        payload: {
          url: tab.url,
        },
      });
    }, 2000);
    return;
  }
  /**
   * I think this `tab.status !== "complete"` should be removed. The above comments
   * on Workday hold true for Lever as well (and I suspect most——maybe all——other pages too)
   *
   * This check was added to support Smart Recruiters:
   * https://github.com/brighthire/brighthire/commit/220d6eb8dd9fe5c705c8a66049e01fa0d5e03a44#diff-b5e5dbb980f84aa48e01888eb3ad589487374a3e6d827374139b22ae4c8f2944R126
   *
   * For now, we'll just sidestep the check for Lever, since that is the main
   * issue report we're getting from users.
   */
  if (tab.status !== "complete" && !isLever) return;
  if (changeInfo.url != null) {
    chrome.tabs.sendMessage(tabId, {
      action: "handleTabUpdate",
      payload: {
        url: changeInfo.url,
      },
    });
  }
});
