import { fetchJson } from "../fetchJson";
import { sendMessage } from "../message";
import { captureException } from "../sentry";
import { getUrlPrefix, getValue, setValue } from "../storage";
import { FALLBACK_CONFIG } from "./UI_CONFIG";

const MAX_CACHE_AGE_IN_MINUTES = 5;
const FETCH_TIMEOUT_IN_SECONDS = 5;

type UiConfig = typeof FALLBACK_CONFIG;

const fetchUiConfig = async (): Promise<UiConfig> => {
  const urlPrefix = await getUrlPrefix();
  try {
    return await fetchJson<UiConfig>(`${urlPrefix}/ui-config`, {
      operation: "fetchUiConfig",
      timeoutMs: 1000 * FETCH_TIMEOUT_IN_SECONDS,
    });
  } catch (err) {
    captureException(err);
    return FALLBACK_CONFIG;
  }
};

/**
 * For the service worker to get the UI config, looking first in the cache
 * and then sending a network request if the cache is missing or stale
 */
export const getUiConfigSw = async (): Promise<UiConfig> => {
  const UI_CONFIG_KEY = "uiConfig";
  const LAST_FETCH_AT_KEY = "uiConfig:lastFetchAt";

  const [cachedValue, lastFetchAt] = await Promise.all([
    getValue<UiConfig | null>(UI_CONFIG_KEY, null),
    getValue<number | null>(LAST_FETCH_AT_KEY, null),
  ]);
  const cacheIsFresh =
    cachedValue &&
    lastFetchAt &&
    Date.now() - lastFetchAt < 1000 * 60 * MAX_CACHE_AGE_IN_MINUTES;

  if (cacheIsFresh) {
    return cachedValue;
  }

  const uiConfig = await fetchUiConfig();
  await Promise.all([
    setValue(UI_CONFIG_KEY, uiConfig),
    setValue(LAST_FETCH_AT_KEY, Date.now()),
  ]);

  return uiConfig;
};

let resolvedConfig: UiConfig | null = null;
/**
 * For content scripts to get the UI config from the service worker
 */
export const getUiConfig = async <T extends keyof UiConfig>(
  key: T,
): Promise<UiConfig[T] | null> => {
  if (resolvedConfig) return resolvedConfig[key] ?? null;
  const messageResponse = await sendMessage({ action: "getUiConfig" });
  const uiConfig = messageResponse?.uiConfig as UiConfig | undefined;
  resolvedConfig = uiConfig ?? FALLBACK_CONFIG;
  const value = resolvedConfig?.[key];

  if (uiConfig && !uiConfig[key]) {
    captureException(
      new Error(`Un-expected UI config key requested: "${key}"`),
    );
  }

  return value ?? null;
};
