/**
 * Tiny wrapper around `fetch` that:
 *   - throws on network errors
 *   - throws on non-OK HTTP responses
 *   - throws on JSON parse errors
 *
 * All thrown errors are `HttpError`, which carries structured context
 * (url, method, status, operation) that Sentry can group on.
 *
 * This intentionally stays small — we ship to the Chrome Web Store and
 * adding a fetch library (ky/axios/etc.) is not worth ~13kB for two
 * call sites.
 */

export type FetchJsonOptions = RequestInit & {
  /** Logical operation name, used for Sentry tags and error messages. */
  operation: string;
  /** Abort the request after this many milliseconds. */
  timeoutMs?: number;
};

export class HttpError extends Error {
  readonly url: string;
  readonly method: string;
  readonly operation: string;
  readonly status?: number;
  readonly kind: "network" | "http" | "parse";

  constructor(
    message: string,
    opts: {
      url: string;
      method: string;
      operation: string;
      kind: "network" | "http" | "parse";
      status?: number;
      cause?: unknown;
    },
  ) {
    super(message);
    this.name = "HttpError";
    this.url = opts.url;
    this.method = opts.method;
    this.operation = opts.operation;
    this.status = opts.status;
    this.kind = opts.kind;
    // Attach cause manually for compatibility with pre-ES2022 lib targets.
    if (opts.cause !== undefined) {
      (this as Error & { cause?: unknown }).cause = opts.cause;
    }
  }
}

export const fetchJson = async <T>(
  url: string,
  options: FetchJsonOptions,
): Promise<T> => {
  const { operation, timeoutMs, signal: callerSignal, ...init } = options;
  const method = (init.method ?? "GET").toUpperCase();

  // Compose caller-supplied signal with our timeout, if any.
  let timeoutHandle: ReturnType<typeof setTimeout> | undefined;
  let signal = callerSignal ?? undefined;
  if (timeoutMs != null) {
    const controller = new AbortController();
    timeoutHandle = setTimeout(() => {
      controller.abort(`${operation} timed out after ${timeoutMs}ms`);
    }, timeoutMs);
    if (callerSignal) {
      callerSignal.addEventListener("abort", () => controller.abort(), {
        once: true,
      });
    }
    signal = controller.signal;
  }

  try {
    let res: Response;
    try {
      res = await fetch(url, { ...init, signal });
    } catch (err) {
      throw new HttpError(`Network error fetching ${operation}`, {
        url,
        method,
        operation,
        kind: "network",
        cause: err,
      });
    }

    if (!res.ok) {
      throw new HttpError(
        `Non-OK response (${res.status}) fetching ${operation}`,
        { url, method, operation, kind: "http", status: res.status },
      );
    }

    try {
      return (await res.json()) as T;
    } catch (err) {
      throw new HttpError(`Failed to parse JSON response for ${operation}`, {
        url,
        method,
        operation,
        kind: "parse",
        status: res.status,
        cause: err,
      });
    }
  } finally {
    if (timeoutHandle !== undefined) clearTimeout(timeoutHandle);
  }
};
