import { CURRENT_USER_CACHE_MIN, fetchCurrentUserUseCache } from "./request";
import { getSuppressWelcomeTab, getUrlPrefix } from "./storage";

export const initCurrentUser = (): void => {
  fetchCurrentUserUseCache();
  const fetchCurrentUserAlarmName = "fetchCurrentUserAlarm";
  chrome.alarms.create(fetchCurrentUserAlarmName, {
    delayInMinutes: CURRENT_USER_CACHE_MIN,
  });
  chrome.alarms.onAlarm.addListener((alarm) => {
    if (alarm.name !== fetchCurrentUserAlarmName) return;
    fetchCurrentUserUseCache();
    chrome.alarms.create(fetchCurrentUserAlarmName, {
      delayInMinutes: CURRENT_USER_CACHE_MIN,
    });
  });

  // open brighthire on install if current user is not signed in
  chrome.runtime.onInstalled.addListener(async (details) => {
    if (details.reason !== "install") return;

    // Skip for enterprise MDM deployments
    const suppressWelcomeTab = await getSuppressWelcomeTab();
    if (suppressWelcomeTab) return;

    const user = await fetchCurrentUserUseCache();
    if (user == null) {
      const url = await getUrlPrefix();
      chrome.tabs.create({
        url: `${url}/sign-in`,
        active: true,
      });
    }
  });
};
