import { getUrlPrefix } from "./storage";
import { isEquivalentIAUrl } from "./url";

export const openInterviewAssistant = async (
  url?: string,
  height?: number,
): Promise<void> => {
  // Use an existing interview assistant tab when available
  const urlPrefix = await getUrlPrefix();
  const tabs = await chrome.tabs.query({
    url: `${urlPrefix}/interview-assistant*`,
  });
  for (let i = 0; i < tabs.length; i += 1) {
    const tab = tabs[i];
    if (tab.id === undefined || tab.url == null) {
      continue;
    }
    const tabsQuery = await chrome.tabs.query({ windowId: tab.windowId });
    if (tabsQuery.length !== 1) {
      continue;
    }
    const window = await chrome.windows.get(tab.windowId);
    if (window.type !== "popup") {
      continue;
    }

    const updateProperties: chrome.tabs.UpdateProperties = { active: true };
    // Only apply the passed url if it's different than the tab's current url
    if (url != null) {
      const tabCurrentUrl = new URL(tab.url, urlPrefix);
      const targetUrl = new URL(url, urlPrefix);

      if (!isEquivalentIAUrl(tabCurrentUrl, targetUrl)) {
        updateProperties.url = targetUrl.href;
      }
    }
    chrome.tabs.update(tab.id, updateProperties);
    chrome.windows.update(tab.windowId, { focused: true });
    return;
  }

  // No existing IA tab was found - open a new popup
  const popupUrl = new URL(url ?? "/interview-assistant", urlPrefix);

  await chrome.windows.create({
    url: popupUrl.href,
    top: 0,
    left: 500,
    width: 500,
    height: height ?? 800,
    type: "popup",
    state: "normal",
    focused: true,
  });
};
