import * as Sentry from "@sentry/browser";

import { fetchJson } from "./fetchJson";
import { logVerbose } from "./logVerbose";
import {
  getCurrentUser,
  getCurrentUserLastFetch,
  getUrlPrefix,
  setCurrentUser,
  setCurrentUserLastFetch,
} from "./storage";

export const CURRENT_USER_CACHE_MIN = 5;

type CurrentUserResponse = { data?: { currentUser?: CurrentUser | null } };

export const fetchCurrentUser = async (): Promise<CurrentUser | null> => {
  const urlPrefix = await getUrlPrefix();
  const operation = "CurrentUser";
  const query = `query CurrentUser {
      currentUser {
        id
        firstName
        lastName
        fullName
        email
        enabledFeatures
        eventImportKeywords {
          id
          keywordText
        }
        organization {
          id
          planEnabled
          allowInPersonMeetings
          workdayQuestionnaireTitles
          workdayOneClickAllFields
          hideAtsCallButton
        }
        showJoinWithBrighthire
        autofillSettings {
          includeAdditionalSummary
          detailLevel
          overallSummaryStyle
          templateId
        }
      }
    }`.replace(/\n/g, "\\n");

  const body = await fetchJson<CurrentUserResponse>(`${urlPrefix}/graphql`, {
    operation,
    method: "POST",
    mode: "cors",
    credentials: "include",
    headers: {
      accept: "*/*",
      "accept-language": "en-US,en;q=0.9",
      "cache-control": "no-cache",
      "content-type": "application/json",
      pragma: "no-cache",
    },
    body: `{
        "operationName":"${operation}",
        "variables":{},
        "query":"${query}"
      }`,
  });

  return body?.data?.currentUser ?? null;
};

export const fetchCurrentUserUseCache =
  async (): Promise<CurrentUser | null> => {
    logVerbose("enter fetchCurrentUserUseCache");
    const lastFetch = await getCurrentUserLastFetch();
    let currentUser: CurrentUser | null = null;
    // cache current user for 5min
    const currentUserCacheMs = 1000 * 60 * CURRENT_USER_CACHE_MIN;
    if (lastFetch + currentUserCacheMs < Date.now()) {
      currentUser = await refreshCurrentUser();
    } else {
      currentUser = await getCurrentUser();
      if (currentUser == null) {
        currentUser = await refreshCurrentUser();
      }
    }

    logVerbose("exit fetchCurrentUserUseCache", currentUser);
    return currentUser;
  };

export const refreshCurrentUser = async (): Promise<CurrentUser | null> => {
  let currentUser: CurrentUser | null;
  try {
    currentUser = await fetchCurrentUser();
  } catch (err) {
    Sentry.captureException(err, {
      tags: { operation: "refreshCurrentUser" },
    });
    // Don't overwrite a previously-cached user or update lastFetch on
    // transient failures — let the next alarm tick retry.
    return await getCurrentUser();
  }
  setCurrentUserLastFetch(Date.now());
  setCurrentUser(currentUser);
  return currentUser;
};
